import math

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def compute_max_gcd(a):
    b = a - 1
    xor_ab = a ^ b
    and_ab = a & b
    return gcd(xor_ab, and_ab)

def main():
    q = int(input())
    results = []
    for _ in range(q):
        a = int(input())
        results.append(compute_max_gcd(a))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
